BEGIN;

CREATE TABLE public.projects(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),owner_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,name TEXT NOT NULL DEFAULT 'Mi reforma',legacy_owner_id UUID UNIQUE REFERENCES auth.users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.project_members(project_id UUID NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN('owner','editor','viewer')),joined_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(project_id,user_id));
CREATE TABLE public.user_active_projects(user_id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,project_id UUID NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.project_invitations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),project_id UUID NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,email TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'editor' CHECK(role IN('editor','viewer')),token UUID NOT NULL DEFAULT gen_random_uuid() UNIQUE,expires_at TIMESTAMPTZ NOT NULL DEFAULT(now()+INTERVAL '7 days'),accepted_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX project_pending_invitation_email_idx ON public.project_invitations(project_id,lower(email)) WHERE accepted_at IS NULL;
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY; ALTER TABLE public.project_members ENABLE ROW LEVEL SECURITY; ALTER TABLE public.user_active_projects ENABLE ROW LEVEL SECURITY; ALTER TABLE public.project_invitations ENABLE ROW LEVEL SECURITY;

CREATE FUNCTION public.is_project_member(p UUID,roles TEXT[] DEFAULT NULL) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM project_members WHERE project_id=p AND user_id=auth.uid() AND(roles IS NULL OR role=ANY(roles)))$$;
CREATE FUNCTION public.current_project_id() RETURNS UUID LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT COALESCE((SELECT a.project_id FROM user_active_projects a JOIN project_members m ON m.project_id=a.project_id AND m.user_id=a.user_id WHERE a.user_id=auth.uid()),(SELECT project_id FROM project_members WHERE user_id=auth.uid() ORDER BY joined_at LIMIT 1))$$;
CREATE FUNCTION public.users_share_project(a UUID,b UUID) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM project_members x JOIN project_members y USING(project_id) WHERE x.user_id=a AND y.user_id=b)$$;
CREATE FUNCTION public.can_access_storage_scope(scope UUID) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT public.is_project_member(scope) OR scope=auth.uid() OR public.users_share_project(auth.uid(),scope)$$;

INSERT INTO public.projects(owner_id,legacy_owner_id) SELECT id,id FROM auth.users;
INSERT INTO public.project_members SELECT id,owner_id,'owner',now() FROM public.projects;
INSERT INTO public.user_active_projects SELECT owner_id,id,now() FROM public.projects;

CREATE FUNCTION public.new_user_project() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE p UUID;BEGIN INSERT INTO projects(owner_id,legacy_owner_id)VALUES(NEW.id,NEW.id)RETURNING id INTO p;INSERT INTO project_members VALUES(p,NEW.id,'owner',now());INSERT INTO user_active_projects VALUES(NEW.id,p,now());RETURN NEW;END$$;
CREATE TRIGGER create_project_after_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.new_user_project();

DO $$DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['material_categories','rooms','materials','category_budgets','inspirations','floor_plans','notes','dashboard_grid_config','dashboard_grid_cells','budget_pdfs','tasks','expenses','suppliers','progress_photos','home_info','home_documents'] LOOP EXECUTE format('ALTER TABLE public.%I ADD COLUMN project_id UUID REFERENCES public.projects(id) ON DELETE CASCADE',t);EXECUTE format('UPDATE public.%I r SET project_id=p.id FROM public.projects p WHERE p.legacy_owner_id=r.user_id',t);EXECUTE format('CREATE INDEX %I ON public.%I(project_id)',t||'_project_idx',t);END LOOP;END$$;
DO $$DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['materials','category_budgets','inspirations','floor_plans','notes','dashboard_grid_config','dashboard_grid_cells','budget_pdfs','tasks','expenses','suppliers','progress_photos','home_info','home_documents'] LOOP EXECUTE format('ALTER TABLE public.%I ALTER COLUMN project_id SET NOT NULL',t);END LOOP;END$$;
ALTER TABLE public.dashboard_grid_config DROP CONSTRAINT dashboard_grid_config_pkey; ALTER TABLE public.dashboard_grid_config ADD COLUMN id UUID DEFAULT gen_random_uuid() PRIMARY KEY; ALTER TABLE public.dashboard_grid_config ADD UNIQUE(project_id);
ALTER TABLE public.dashboard_grid_cells DROP CONSTRAINT dashboard_grid_cells_user_id_row_index_col_index_key; ALTER TABLE public.dashboard_grid_cells ADD UNIQUE(project_id,row_index,col_index);
ALTER TABLE public.category_budgets DROP CONSTRAINT category_budgets_user_id_category_id_key; ALTER TABLE public.category_budgets ADD UNIQUE(project_id,category_id);
ALTER TABLE public.home_info DROP CONSTRAINT home_info_user_id_key; ALTER TABLE public.home_info ADD UNIQUE(project_id);

CREATE FUNCTION public.assign_current_project() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN NEW.project_id:=COALESCE(NEW.project_id,public.current_project_id());NEW.user_id:=auth.uid();IF NEW.project_id IS NULL THEN RAISE EXCEPTION 'No hay un proyecto activo';END IF;RETURN NEW;END$$;
DO $$DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['material_categories','rooms','materials','category_budgets','inspirations','floor_plans','notes','dashboard_grid_config','dashboard_grid_cells','budget_pdfs','tasks','expenses','suppliers','progress_photos','home_info','home_documents'] LOOP EXECUTE format('CREATE TRIGGER assign_current_project BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION public.assign_current_project()',t);END LOOP;END$$;

DO $$DECLARE t TEXT;p RECORD;BEGIN FOREACH t IN ARRAY ARRAY['material_categories','rooms','materials','category_budgets','inspirations','floor_plans','notes','dashboard_grid_config','dashboard_grid_cells','budget_pdfs','tasks','expenses','suppliers','progress_photos','home_info','home_documents','task_items'] LOOP FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename=t LOOP EXECUTE format('DROP POLICY %I ON public.%I',p.policyname,t);END LOOP;END LOOP;END$$;
DO $$DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['materials','category_budgets','inspirations','floor_plans','notes','dashboard_grid_config','dashboard_grid_cells','budget_pdfs','tasks','expenses','suppliers','progress_photos','home_info','home_documents'] LOOP EXECUTE format('CREATE POLICY "project read" ON public.%I FOR SELECT TO authenticated USING(project_id=public.current_project_id() AND public.is_project_member(project_id))',t);EXECUTE format('CREATE POLICY "project insert" ON public.%I FOR INSERT TO authenticated WITH CHECK(project_id=public.current_project_id() AND public.is_project_member(project_id,ARRAY[''owner'',''editor'']))',t);EXECUTE format('CREATE POLICY "project update" ON public.%I FOR UPDATE TO authenticated USING(project_id=public.current_project_id() AND public.is_project_member(project_id,ARRAY[''owner'',''editor''])) WITH CHECK(project_id=public.current_project_id())',t);EXECUTE format('CREATE POLICY "project delete" ON public.%I FOR DELETE TO authenticated USING(project_id=public.current_project_id() AND public.is_project_member(project_id,ARRAY[''owner'',''editor'']))',t);END LOOP;END$$;
CREATE POLICY "category read" ON material_categories FOR SELECT TO authenticated USING(project_id IS NULL OR project_id=current_project_id()); CREATE POLICY "category write" ON material_categories FOR ALL TO authenticated USING(project_id=current_project_id() AND is_project_member(project_id,ARRAY['owner','editor'])) WITH CHECK(project_id=current_project_id() AND is_project_member(project_id,ARRAY['owner','editor']));
CREATE POLICY "room read" ON rooms FOR SELECT TO authenticated USING(project_id IS NULL OR project_id=current_project_id()); CREATE POLICY "room write" ON rooms FOR ALL TO authenticated USING(project_id=current_project_id() AND is_project_member(project_id,ARRAY['owner','editor'])) WITH CHECK(project_id=current_project_id() AND is_project_member(project_id,ARRAY['owner','editor']));
CREATE POLICY "items read" ON task_items FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM tasks t WHERE t.id=task_id AND t.project_id=current_project_id())); CREATE POLICY "items write" ON task_items FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM tasks t WHERE t.id=task_id AND is_project_member(t.project_id,ARRAY['owner','editor']))) WITH CHECK(EXISTS(SELECT 1 FROM tasks t WHERE t.id=task_id AND is_project_member(t.project_id,ARRAY['owner','editor'])));
CREATE POLICY "member projects" ON projects FOR SELECT TO authenticated USING(is_project_member(id)); CREATE POLICY "member list" ON project_members FOR SELECT TO authenticated USING(is_project_member(project_id)); CREATE POLICY "own active" ON user_active_projects FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY "owner invitations" ON project_invitations FOR SELECT TO authenticated USING(is_project_member(project_id,ARRAY['owner'])); CREATE POLICY "owner deletes invitation" ON project_invitations FOR DELETE TO authenticated USING(is_project_member(project_id,ARRAY['owner']));

CREATE FUNCTION public.get_workspace_context() RETURNS TABLE(project_id UUID,workspace_owner_id UUID,project_name TEXT,role TEXT,owner_email TEXT) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,auth AS $$SELECT p.id,p.owner_id,p.name,m.role,COALESCE(u.email::TEXT,'') FROM projects p JOIN project_members m ON m.project_id=p.id AND m.user_id=auth.uid() JOIN auth.users u ON u.id=p.owner_id WHERE p.id=current_project_id()$$;
CREATE FUNCTION public.list_user_projects() RETURNS TABLE(project_id UUID,name TEXT,role TEXT,is_active BOOLEAN) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT p.id,p.name,m.role,p.id=current_project_id() FROM projects p JOIN project_members m ON m.project_id=p.id WHERE m.user_id=auth.uid() ORDER BY p.created_at$$;
CREATE FUNCTION public.switch_project(p_project_id UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN IF NOT is_project_member(p_project_id)THEN RAISE EXCEPTION 'No tienes acceso';END IF;INSERT INTO user_active_projects VALUES(auth.uid(),p_project_id,now())ON CONFLICT(user_id)DO UPDATE SET project_id=EXCLUDED.project_id,updated_at=now();END$$;
CREATE FUNCTION public.create_project(p_name TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE p UUID;n TEXT:=trim(p_name);BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Debes iniciar sesión';END IF;IF n='' OR length(n)>80 THEN RAISE EXCEPTION 'El nombre debe tener entre 1 y 80 caracteres';END IF;INSERT INTO projects(owner_id,name)VALUES(auth.uid(),n)RETURNING id INTO p;INSERT INTO project_members VALUES(p,auth.uid(),'owner',now());INSERT INTO user_active_projects VALUES(auth.uid(),p,now())ON CONFLICT(user_id)DO UPDATE SET project_id=EXCLUDED.project_id,updated_at=now();RETURN p;END$$;
CREATE FUNCTION public.update_project(p_project_id UUID,p_name TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE n TEXT:=trim(p_name);BEGIN IF NOT is_project_member(p_project_id,ARRAY['owner'])THEN RAISE EXCEPTION 'Solo el propietario puede editar la reforma';END IF;IF n='' OR length(n)>80 THEN RAISE EXCEPTION 'El nombre debe tener entre 1 y 80 caracteres';END IF;UPDATE projects SET name=n,updated_at=now()WHERE id=p_project_id;END$$;
CREATE FUNCTION public.list_workspace_members() RETURNS TABLE(user_id UUID,email TEXT,role TEXT,joined_at TIMESTAMPTZ) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,auth AS $$SELECT u.id,COALESCE(u.email::TEXT,''),m.role,m.joined_at FROM project_members m JOIN auth.users u ON u.id=m.user_id WHERE m.project_id=current_project_id() ORDER BY m.joined_at$$;
CREATE FUNCTION public.list_workspace_invitations() RETURNS TABLE(id UUID,email TEXT,role TEXT,token UUID,expires_at TIMESTAMPTZ,created_at TIMESTAMPTZ) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT i.id,i.email,i.role,i.token,i.expires_at,i.created_at FROM project_invitations i WHERE i.project_id=current_project_id() AND is_project_member(i.project_id,ARRAY['owner']) AND i.accepted_at IS NULL AND i.expires_at>now()$$;
CREATE FUNCTION public.create_workspace_invitation(p_email TEXT,p_role TEXT DEFAULT 'editor') RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth AS $$DECLARE e TEXT:=lower(trim(p_email));tok UUID;p UUID:=current_project_id();BEGIN IF NOT is_project_member(p,ARRAY['owner'])THEN RAISE EXCEPTION 'Solo el propietario puede invitar';END IF;IF p_role NOT IN('editor','viewer')THEN RAISE EXCEPTION 'Rol no válido';END IF;IF e='' OR position('@' IN e)<2 THEN RAISE EXCEPTION 'Email no válido';END IF;IF EXISTS(SELECT 1 FROM project_members m JOIN auth.users u ON u.id=m.user_id WHERE m.project_id=p AND lower(u.email::TEXT)=e)THEN RAISE EXCEPTION 'Esta persona ya tiene acceso';END IF;DELETE FROM project_invitations WHERE project_id=p AND lower(email)=e AND accepted_at IS NULL;INSERT INTO project_invitations(project_id,email,role)VALUES(p,e,p_role)RETURNING token INTO tok;RETURN tok;END$$;
CREATE FUNCTION public.accept_workspace_invitation(p_token UUID) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth AS $$DECLARE i project_invitations%ROWTYPE;e TEXT;BEGIN SELECT lower(COALESCE(email::TEXT,''))INTO e FROM auth.users WHERE id=auth.uid();SELECT * INTO i FROM project_invitations WHERE token=p_token AND accepted_at IS NULL FOR UPDATE;IF NOT FOUND OR i.expires_at<=now()THEN RAISE EXCEPTION 'La invitación no existe o ha caducado';END IF;IF e<>lower(i.email)THEN RAISE EXCEPTION 'La invitación pertenece a otro email';END IF;INSERT INTO project_members VALUES(i.project_id,auth.uid(),i.role,now())ON CONFLICT(project_id,user_id)DO UPDATE SET role=EXCLUDED.role;INSERT INTO user_active_projects VALUES(auth.uid(),i.project_id,now())ON CONFLICT(user_id)DO UPDATE SET project_id=EXCLUDED.project_id,updated_at=now();UPDATE project_invitations SET accepted_at=now()WHERE id=i.id;RETURN jsonb_build_object('project_id',i.project_id,'role',i.role);END$$;
CREATE FUNCTION public.remove_workspace_member(p_user_id UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE p UUID:=current_project_id();BEGIN IF NOT is_project_member(p,ARRAY['owner'])THEN RAISE EXCEPTION 'Solo el propietario puede retirar accesos';END IF;DELETE FROM project_members WHERE project_id=p AND user_id=p_user_id AND role<>'owner';DELETE FROM user_active_projects WHERE user_id=p_user_id AND project_id=p;END$$;

DROP POLICY IF EXISTS "Users can upload own home documents" ON storage.objects; DROP POLICY IF EXISTS "Users can update own home documents" ON storage.objects; DROP POLICY IF EXISTS "Users can delete own home documents" ON storage.objects; DROP POLICY IF EXISTS "Users can view own home documents files" ON storage.objects;
CREATE POLICY "project home documents insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='home-documents' AND can_access_storage_scope(((storage.foldername(name))[1])::UUID)); CREATE POLICY "project home documents read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='home-documents' AND can_access_storage_scope(((storage.foldername(name))[1])::UUID)); CREATE POLICY "project home documents update" ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='home-documents' AND can_access_storage_scope(((storage.foldername(name))[1])::UUID)); CREATE POLICY "project home documents delete" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='home-documents' AND can_access_storage_scope(((storage.foldername(name))[1])::UUID));
CREATE POLICY "project members delete shared uploads" ON storage.objects FOR DELETE TO authenticated USING(bucket_id IN('images','material-images','budget-pdfs') AND users_share_project(auth.uid(),owner));

CREATE OR REPLACE FUNCTION public.accept_budget_pdf(p_budget_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$DECLARE b budget_pdfs%ROWTYPE;e UUID;BEGIN SELECT * INTO b FROM budget_pdfs WHERE id=p_budget_id AND project_id=current_project_id() FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Presupuesto no encontrado';END IF;IF b.total_amount IS NULL OR b.total_amount<=0 THEN RAISE EXCEPTION 'Indica el importe antes de aceptar';END IF;IF b.expense_id IS NOT NULL THEN RETURN b.expense_id;END IF;INSERT INTO expenses(user_id,project_id,supplier_id,title,category,vendor,budgeted_amount,amount,paid_amount,expense_date,notes)VALUES(auth.uid(),b.project_id,b.supplier_id,b.name,'Mano de obra',COALESCE((SELECT name FROM suppliers WHERE id=b.supplier_id),''),b.total_amount,b.total_amount,0,CURRENT_DATE,b.notes)RETURNING id INTO e;UPDATE budget_pdfs SET status='Aceptado',accepted_at=now(),expense_id=e,updated_at=now()WHERE id=p_budget_id;RETURN e;END$$;

REVOKE ALL ON FUNCTION public.new_user_project(),public.assign_current_project() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.is_project_member(UUID,TEXT[]),public.users_share_project(UUID,UUID),public.can_access_storage_scope(UUID),public.current_project_id() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_workspace_context(),public.list_user_projects(),public.switch_project(UUID),public.create_project(TEXT),public.update_project(UUID,TEXT),public.list_workspace_members(),public.list_workspace_invitations(),public.create_workspace_invitation(TEXT,TEXT),public.accept_workspace_invitation(UUID),public.remove_workspace_member(UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_workspace_context(),public.list_user_projects(),public.switch_project(UUID),public.create_project(TEXT),public.update_project(UUID,TEXT),public.list_workspace_members(),public.list_workspace_invitations(),public.create_workspace_invitation(TEXT,TEXT),public.accept_workspace_invitation(UUID),public.remove_workspace_member(UUID),public.current_project_id(),public.is_project_member(UUID,TEXT[]),public.users_share_project(UUID,UUID),public.can_access_storage_scope(UUID) TO authenticated;
GRANT SELECT ON public.projects,public.project_members,public.user_active_projects TO authenticated; GRANT SELECT,DELETE ON public.project_invitations TO authenticated;
COMMIT;
